import {
  BarChart3,
  Folder,
  CheckCircle,
  Calendar,
  MessageSquare,
  FileText,
  CreditCard,
  Shield,
  Settings,
  X
} from 'lucide-react'

const Sidebar = ({ isOpen, onClose, activeTab, onTabChange }) => {
  const menuItems = [
    { id: 'overview', name: 'Vue d\'ensemble', icon: BarChart3 },
    { id: 'projects', name: 'Projets', icon: Folder },
    { id: 'tasks', name: 'Tâches', icon: CheckCircle },
    { id: 'calendar', name: 'Calendrier', icon: Calendar },
    { id: 'messages', name: 'Messages', icon: MessageSquare },
    { id: 'documents', name: 'Documents', icon: FileText },
    { id: 'billing', name: 'Facturation', icon: CreditCard },
    { id: 'security', name: 'Sécurité', icon: Shield },
    { id: 'settings', name: 'Paramètres', icon: Settings },
  ]

  return (
    <>
      {/* Overlay pour mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
          onClick={onClose}
        ></div>
      )}

      {/* Sidebar */}
      <div className={`fixed inset-y-0 left-0 z-50 w-64 bg-gray-900 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition duration-300 ease-in-out lg:static lg:inset-0`}>
        <div className="flex items-center justify-between h-16 px-4 bg-gray-800">
          <h1 className="text-xl font-bold text-white">Dashboard</h1>
          <button 
            onClick={onClose}
            className="lg:hidden text-gray-400 hover:text-white"
          >
            <X className="h-6 w-6" />
          </button>
        </div>

        <nav className="mt-8 px-4">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => {
                onTabChange(item.id)
                onClose()
              }}
              className={`w-full flex items-center px-4 py-3 mb-2 rounded-lg transition duration-200 ${
                activeTab === item.id 
                  ? 'bg-blue-600 text-white' 
                  : 'text-gray-300 hover:bg-gray-800 hover:text-white'
              }`}
            >
              <item.icon className="h-5 w-5 mr-3" />
              {item.name}
            </button>
          ))}
        </nav>
      </div>
    </>
  )
}

export default Sidebar
